// Drift guard for ALWAYS-ON.md's condensed paste-ready block.
//
// That block is the ONE place in this repo where the rule is duplicated by hand
// instead of code-generated by embed.mjs, because a ~15 KB rule cannot go in a
// preferences field that is prepended to every conversation. Hand-written copies
// of a single source of truth go stale silently; everything else here is guarded
// against exactly that, so this is too.
//
// What it can prove: the byte counts ALWAYS-ON.md states about itself and about
// rule/closure-scheduler.md are both true right now. Any edit to the rule changes
// its size and fails this check, which forces a human to re-read the condensed
// block and decide whether it still says the same thing.
//
// What it CANNOT prove: that the condensed block is semantically faithful. A
// size-preserving rule edit slips through, and no byte count can tell you a
// paraphrase drifted. Treat a failure as "go re-read both", not "fix the number".
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const alwaysOnPath = join(root, "ALWAYS-ON.md");
const rulePath = join(root, "rule", "closure-scheduler.md");

const alwaysOn = readFileSync(alwaysOnPath, "utf8");
const ruleBytes = Buffer.byteLength(readFileSync(rulePath, "utf8"), "utf8");

const fence = alwaysOn.match(/```text\n([\s\S]*?)\n```/);
const citedBlock = alwaysOn.match(/This block is \*\*([\d,]+) bytes\*\*/);
const citedRule = alwaysOn.match(/The full rule is ([\d,]+) bytes/);

const num = (m) => (m ? Number(m[1].replace(/,/g, "")) : null);
const blockBytes = fence ? Buffer.byteLength(fence[1], "utf8") : null;

const checks = {
  "ALWAYS-ON.md carries a ```text paste block": fence !== null,
  "ALWAYS-ON.md states its own block size": citedBlock !== null,
  "ALWAYS-ON.md states the full rule size": citedRule !== null,
  "stated block size matches the actual block": num(citedBlock) === blockBytes,
  "stated rule size matches rule/closure-scheduler.md":
    num(citedRule) === ruleBytes,
  // Not a style preference: this is the whole reason the block is condensed.
  // If it ever approaches the full rule there is no point pasting it.
  "condensed block stays under half the full rule":
    blockBytes !== null && blockBytes * 2 < ruleBytes,
};

console.log("paste block bytes:", blockBytes, "| stated:", num(citedBlock));
console.log("rule bytes:", ruleBytes, "| stated:", num(citedRule));

let ok = true;
for (const [name, pass] of Object.entries(checks)) {
  console.log(`${pass ? "PASS" : "FAIL"} — ${name}`);
  if (!pass) ok = false;
}

if (!ok) {
  console.error(
    "\ncheck-always-on: ALWAYS-ON.md is out of step with rule/closure-scheduler.md.\n" +
      "Re-read the condensed paste block against the full rule, update it if the\n" +
      "contract changed, then correct the byte counts in the surrounding prose.\n" +
      "Do NOT just edit the numbers — the numbers are the tripwire, not the point.",
  );
}
console.log(ok ? "ALWAYS-ON OK" : "ALWAYS-ON FAILED");
process.exit(ok ? 0 : 1);
